// EDIT THESE VALUES (one place per workflow). No other node needs changing.
const supabaseUrl = 'https://abcdefghijklmnopqrst.supabase.co';      // Supabase project URL
const pokeUrl = 'https://your-instance.app.n8n.cloud/webhook/sandbox-sme-poke';          // WF4 "Action runner" production webhook URL
const pokeKey = 'REPLACE_WITH_POKE_SECRET';                   // same value as the "Poke secret" credential

return [{ json: {
  supabaseUrl: supabaseUrl.replace(/\/+$/, ''),
  pokeUrl,
  pokeKey,
} }];

// Parse each Gmail message into one database call. Parsing only; the database decides what it means.
// Only mail about this system is handled: replies sent to the +scheduling Reply-To address, and bounces
// of emails this system sent (they quote that address). Everything else in the shared inbox is skipped.
const SYS = 'scheduling-mailbox+scheduling@yourcompany.com';
function hdr(m, name) {
  const h = m.headers; const want = name.toLowerCase(); let v;
  if (Array.isArray(h)) {
    const f = h.find(x => String(x.name || x.key || '').toLowerCase() === want);
    v = f && (f.value || f.line);
  } else if (h && typeof h === 'object') {
    for (const k of Object.keys(h)) if (k.toLowerCase() === want) v = h[k];
  }
  if (v == null) return '';
  v = typeof v === 'object' ? (v.text || v.value || JSON.stringify(v)) : String(v);
  return v.replace(new RegExp('^' + want + ':\\s*', 'i'), '').trim();
}
function stripQuoted(t) {
  const lines = String(t || '').replace(/\r\n/g, '\n').split('\n');
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i];
    if (/^\s*>/.test(l)) break;
    if (/^-{2,}\s*Original Message\s*-{2,}/i.test(l)) break;
    if (/^On\s.+/.test(l) && /wrote:\s*$/.test(l + ' ' + (lines[i + 1] || ''))) break;
    out.push(l);
  }
  return out.join('\n').trim() || String(t || '').trim();
}
function failedRecipient(m, text) {
  const x = hdr(m, 'x-failed-recipients');
  if (x) return x.split(',')[0].trim();
  const pats = [
    /Final-Recipient:\s*rfc822;\s*<?([^\s<>;]+@[^\s<>;]+)/i,
    /Original-Recipient:\s*rfc822;\s*<?([^\s<>;]+@[^\s<>;]+)/i,
    /delivered to\s+<?([^\s<>]+@[^\s<>]+)/i,
  ];
  for (const p of pats) { const r = text.match(p); if (r) return r[1].replace(/[>.,;:]+$/, ''); }
  const to = String((m.to && m.to.text) || hdr(m, 'to')).toLowerCase();
  const skip = /mailer-daemon|postmaster|no-?reply|@google\.com$|@googlemail\.com$|^scheduling-mailbox/i;
  const all = text.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [];
  return all.find(a => !skip.test(a) && !to.includes(a.toLowerCase())) || '';
}

const out = [];
for (const item of $input.all()) {
  const m = item.json || {};
  if (!m.id) continue;
  const from = String((m.from && (m.from.text || (m.from.value && m.from.value[0] && m.from.value[0].address))) || hdr(m, 'from') || m.From || '');
  const subject = String(m.subject || hdr(m, 'subject') || m.Subject || '');
  const text = String(m.text || (m.html ? String(m.html).replace(/<[^>]+>/g, ' ') : '') || m.snippet || '');
  const received = m.date ? new Date(m.date) : null;
  const isBounce = /mailer-daemon|postmaster/i.test(from)
    || /delivery status notification|undeliverable|undelivered mail|mail delivery (failed|failure|subsystem)/i.test(subject);
  const addressedTo = (JSON.stringify(m.to || '') + ' ' + JSON.stringify(m.cc || '') + ' ' + hdr(m, 'delivered-to') + ' ' + hdr(m, 'to')).toLowerCase();
  if (isBounce ? !text.toLowerCase().includes(SYS) : !addressedTo.includes(SYS)) continue;
  if (isBounce) {
    out.push({ json: { gmail_id: m.id, rpc: 'record_bounce', args: {
      p_email: failedRecipient(m, text),
      p_external_id: m.id,
      p_detail: (subject + ': ' + text.replace(/\s+/g, ' ')).slice(0, 500),
    } } });
  } else {
    out.push({ json: { gmail_id: m.id, rpc: 'record_inbound_message', args: {
      p_channel: 'Email',
      p_from: from,
      p_subject: subject || null,
      p_body: stripQuoted(text).slice(0, 5000),
      p_external_id: m.id,
      p_received_at: received && !isNaN(received) ? received.toISOString() : null,
      p_summary: null,
    } } });
  }
}
return out;

// Keep only messages written by the instructor who owns the channel, oldest first.
const watch = $('Get watchlist').all();
const cutoff = Date.now() - 3 * 24 * 3600 * 1000;
const byId = (a, b) => (BigInt(a.id) < BigInt(b.id) ? -1 : BigInt(a.id) > BigInt(b.id) ? 1 : 0);
const out = [];
$input.all().forEach((item, idx) => {
  const w = (watch[(item.pairedItem && item.pairedItem.item) ?? idx] || {}).json || {};
  const r = item.json || {};
  if (!w.channel_id || r.error || r.statusCode !== 200 || !Array.isArray(r.body)) return;
  for (const m of r.body.slice().sort(byId)) {
    if (!m.author || String(m.author.id) !== String(w.discord_user_id)) continue;
    if (!w.last_message_id && Date.parse(m.timestamp) < cutoff) continue;
    const parts = [m.content || ''];
    for (const a of m.attachments || []) parts.push('[attachment] ' + a.url);
    const body = parts.join('\n').trim();
    if (!body) continue;
    out.push({ json: { channel_id: w.channel_id, rpc: 'record_inbound_message', args: {
      p_channel: 'Discord',
      p_from: String(m.author.id),
      p_subject: null,
      p_body: body.slice(0, 5000),
      p_external_id: String(m.id),
      p_received_at: m.timestamp || null,
      p_summary: null,
    } } });
  }
});
return out;

// Newest message id per channel. Skip channels that could not be read or where a record failed.
const watch = $('Get watchlist').all();
const failed = new Set();
try {
  const picked = $('Pick instructor replies').all();
  $('Record Discord reply').all().forEach((r, i) => {
    if (r.json && r.json.error && picked[i]) failed.add(picked[i].json.channel_id);
  });
} catch (e) { /* no replies were recorded this run */ }
const out = [];
$input.all().forEach((item, idx) => {
  const w = (watch[(item.pairedItem && item.pairedItem.item) ?? idx] || {}).json || {};
  const r = item.json || {};
  if (!w.channel_id || r.error || r.statusCode !== 200 || !Array.isArray(r.body) || !r.body.length) return;
  if (failed.has(w.channel_id)) return;
  const newest = r.body.map(m => String(m.id)).reduce((a, b) => (BigInt(b) > BigInt(a) ? b : a));
  out.push({ json: { p_channel_id: w.channel_id, p_last_message_id: newest } });
});
return out;
